`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (loop). Reference: golden/reference (memory__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  reg reset;
  wire rd_clk = tb_clk;
  reg [2:0] rd_add;
  wire wr_clk = tb_clk;
  reg [2:0] wr_add;
  reg [31:0] data_in;
  reg wr_en;
  reg rd_en;
  wire [31:0] data_out; wire [31:0] ref_data_out;
  memory dut (.reset(reset), .rd_clk(rd_clk), .rd_add(rd_add), .wr_clk(wr_clk), .wr_add(wr_add), .data_in(data_in), .wr_en(wr_en), .rd_en(rd_en), .data_out(data_out));
  memory__ref ref_i (.reset(reset), .rd_clk(rd_clk), .rd_add(rd_add), .wr_clk(wr_clk), .wr_add(wr_add), .data_in(data_in), .wr_en(wr_en), .rd_en(rd_en), .data_out(ref_data_out));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1)
      if (ref_data_out[tb_b] !== 1'bx && ref_data_out[tb_b] !== 1'bz && data_out[tb_b] !== ref_data_out[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 32;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: data_out = %h, expected %h", $time, tb_cyc, data_out, ref_data_out);
      end
  end endtask
  task tb_props; begin
  end endtask
  reg [31:0] tbc_p_data_out, tbc_t_data_out;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_data_out = tbc_t_data_out | ((ref_data_out ^ tbc_p_data_out) & ~(ref_data_out ^ ref_data_out)); tbc_p_data_out = ref_data_out;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_data_out) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1) if (tbc_t_data_out[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 1 checked outputs toggled, %0d of 32 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 11; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    reset = 0; rd_add = 0; wr_add = 0; data_in = 0; wr_en = 0; rd_en = 0; reset = 1;
    tbc_t_data_out = 0; tbc_p_data_out = 0;
    for (tb_cyc = 0; tb_cyc < 200; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      reset = (tb_cyc < 4) ? 1'b1 : (tb_rand(0) % 40 == 0);
      rd_add = {tb_rand(0)};
      wr_add = {tb_rand(0)};
      data_in = tb_flit(0);
      wr_en = {tb_rand(0)};
      rd_en = {tb_rand(0)};
      if (wr_en && rd_en && wr_add == rd_add) rd_en = 1'b0;
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    if (tb_mis + tb_perr == 0) $display("ALL TESTS PASSED");
    else $display("FAIL: %0d mismatches, %0d property errors", tb_mis, tb_perr);
    $finish;
  end
endmodule

// ---- reference copy of the golden module (children come from lib/)
`timescale 1ns / 1ps





















module memory__ref(reset, rd_clk, rd_add, wr_clk, wr_add, data_in, wr_en, rd_en, data_out);
 input reset ;
       input rd_clk ;
       input [2:0] rd_add ;
       input rd_en ;
       input wr_clk ;
       input [2:0] wr_add ;
       input wr_en ;
        input [31:0] data_in ;
       output [31:0] data_out ;
        
        reg [31:0] data_out ;
        reg [31:0] mem [7:0] ;    
   
       
     
   
   
        always @ (posedge wr_clk)
        begin
               if (wr_en)
                   mem [wr_add] = data_in ;            
        end 
   
        always @ (posedge rd_clk)
        begin
            if (reset)
                data_out = 32'b01100000000000000000000000000000 ; 
         else
           begin
               if (rd_en)
                   data_out = mem[rd_add] ;
            else
                
                data_out=data_out;
           end
       end 
    
endmodule
